    },
    {
      "question": "Combien d'avis notés au moins 4 et créés depuis 2024 concernent chaque membre évalué ?",
      "sql": "SELECT reviewee_id, COUNT(*) FROM reviews WHERE score >= 4 AND created_at >= '2024-01-01' GROUP BY reviewee_id"
    },
    {
      "question": "Combien d'offres actives avec au moins deux places disponibles partent de chaque ville ?",
      "sql": "SELECT departure_city, COUNT(*) FROM ride_offers WHERE status = 'active' AND available_seats >= 2 GROUP BY departure_city"
    },
    {
      "question": "Combien de véhicules à essence construits depuis 2020 sont associés à chaque propriétaire ?",
      "sql": "SELECT owner_id, COUNT(*) FROM vehicles WHERE fuel_type = 'gasoline' AND model_year >= 2020 GROUP BY owner_id"
    },
    {
      "question": "Combien de réservations effectuées avant 2024 par des passagers dont l'identifiant dépasse 100 sont regroupées par statut ?",
